import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  Fragment,
  type ReactNode,
} from 'react';
import { zhCN, type Dictionary } from './locales/zh-CN';
import { enUS } from './locales/en-US';

export type Locale = 'zh-CN' | 'en-US';

const DICTIONARIES: Record<Locale, Dictionary> = {
  'zh-CN': zhCN,
  'en-US': enUS,
};

const STORAGE_KEY = 'coco-toast-locale';

function detectBrowserLocale(): Locale {
  if (typeof navigator === 'undefined') return 'zh-CN';
  const lang = navigator.language || (navigator as Navigator & { userLanguage?: string }).userLanguage || 'zh-CN';
  if (lang.toLowerCase().startsWith('zh')) return 'zh-CN';
  return 'en-US';
}

function getInitialLocale(): Locale {
  if (typeof localStorage === 'undefined') return detectBrowserLocale();
  const stored = localStorage.getItem(STORAGE_KEY) as Locale | null;
  if (stored && stored in DICTIONARIES) return stored;
  return detectBrowserLocale();
}

interface I18nContextValue {
  locale: Locale;
  t: Dictionary;
  setLocale: (locale: Locale) => void;
  toggleLocale: () => void;
}

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(getInitialLocale);

  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const setLocale = useCallback((next: Locale) => {
    setLocaleState(next);
    try {
      localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* ignore quota errors */
    }
  }, []);

  const toggleLocale = useCallback(() => {
    setLocale(locale === 'zh-CN' ? 'en-US' : 'zh-CN');
  }, [locale, setLocale]);

  const value: I18nContextValue = {
    locale,
    t: DICTIONARIES[locale],
    setLocale,
    toggleLocale,
  };

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used within I18nProvider');
  return ctx;
}

/** Simple interpolation: replaces {name} placeholders with provided params. */
export function format(str: string, params?: Record<string, string>): string {
  if (!params) return str;
  return str.replace(/\{(\w+)\}/g, (_, key) => params[key] ?? `{${key}}`);
}

/**
 * Render a translated string containing `{accent}...{/accent}` markers into
 * React nodes, wrapping marked segments in <span className={accentClassName}>.
 */
export function renderWithAccent(str: string, accentClassName: string): ReactNode[] {
  const parts = str.split(/(\{accent\}.*?\{\/accent\})/g);
  return parts.map((part, i) => {
    const match = part.match(/^\{accent\}(.*)\{\/accent\}$/s);
    if (match) {
      return (
        <span key={i} className={accentClassName}>
          {match[1]}
        </span>
      );
    }
    return <Fragment key={i}>{part}</Fragment>;
  });
}
