import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { useI18n } from '../i18n';
import {
  createPreorder,
  fetchPrices,
  type Currency,
  type PreorderData,
} from '../lib/paymentApi';
import {
  isPaddleConfigured,
  openPaddleCheckout,
  clearPaddleCallbacks,
} from '../lib/paddle';
import PaymentLayout from '../components/PaymentLayout';
import './PreorderPage.css';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Status = 'idle' | 'submitting' | 'redirecting' | 'paddle_open' | 'mock' | 'error';

export default function PreorderPage() {
  const { t } = useI18n();
  const [currency, setCurrency] = useState<Currency>('CNY');
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState<string | null>(null);
  const [status, setStatus] = useState<Status>('idle');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [mockNote, setMockNote] = useState<string | null>(null);
  const [paymentHtml, setPaymentHtml] = useState<string | null>(null);
  // 服务端“当前价”（金额不带符号）。null = 尚未取到/失败，此时回退到 i18n 的展示价。
  const [currentPrice, setCurrentPrice] = useState<{
    cny: string | null;
    usd: string | null;
  }>({ cny: null, usd: null });

  const formSlotRef = useRef<HTMLDivElement | null>(null);
  const autoSubmittedRef = useRef(false);

  // 挂载时拉取“当前价”，覆盖原 i18n 硬编码的现价（原价 preorder__currency-original 保持 i18n）。
  // 后端 USD 价从 Paddle 获取并缓存 1 小时，CNY 价读服务端 PRODUCT_PRICE_CNY env。
  useEffect(() => {
    let cancelled = false;
    fetchPrices()
      .then((data) => {
        if (cancelled) return;
        setCurrentPrice({ cny: data.cny.amount, usd: data.usd.amount });
      })
      .catch(() => {
        // 拉取失败不阻断购买页，回退到 i18n 内置展示价
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // 把服务器返回的自动提交表单嵌入页面并触发提交。
  // 直接 innerHTML 时其中的 <script> 不会执行，需手动执行。
  useEffect(() => {
    if (!paymentHtml || !formSlotRef.current || autoSubmittedRef.current) return;
    autoSubmittedRef.current = true;
    const slot = formSlotRef.current;
    slot.innerHTML = paymentHtml;
    slot.querySelectorAll('script').forEach((s) => {
      try {
        new Function(s.textContent || '').call(window);
      } catch {
        /* 忽略单个脚本执行失败，交给手动跳转兜底 */
      }
    });
  }, [paymentHtml]);

  const handleSubmit = async () => {
    const value = email.trim();
    if (!EMAIL_RE.test(value)) {
      setEmailError(t.preorder.emailInvalid);
      return;
    }
    setEmailError(null);
    setErrorMsg(null);
    const returnUrl = `${window.location.origin}/pay/result`;

    // USD 走 Paddle Checkout overlay：不再调用 preorder 接口，直接打开收银台。
    // Paddle 在 checkout.completed 事件里回传 transaction_id (txn_ 前缀)，
    // 用它当 order_id 跳到 /pay/result，由服务端按需查 Paddle API。
    if (currency === 'USD') {
      if (!isPaddleConfigured()) {
        setErrorMsg(t.preorder.paddleNotConfigured);
        setStatus('error');
        return;
      }
      setStatus('paddle_open');
      try {
        await openPaddleCheckout({
          email: value,
          onCompleted: (data) => {
            clearPaddleCallbacks();
            const txnId = (data as { transaction_id?: string }).transaction_id;
            if (!txnId) {
              // 理论上 checkout.completed 一定会带 transaction_id
              setErrorMsg(t.preorder.paddleError);
              setStatus('error');
              return;
            }
            window.location.href = `${returnUrl}?payment_channel=paddle&transaction_id=${encodeURIComponent(txnId)}`;
          },
          onClosed: () => {
            clearPaddleCallbacks();
            setStatus('idle');
          },
          onError: () => {
            clearPaddleCallbacks();
            setErrorMsg(t.preorder.paddleError);
            setStatus('error');
          },
        });
      } catch (e) {
        setErrorMsg(e instanceof Error ? e.message : String(e));
        setStatus('error');
      }
      return;
    }

    // CNY 走支付宝：先 preorder 拿 payment_html，再自动提交跳到支付宝收银台
    setStatus('submitting');
    try {
      const data: PreorderData = await createPreorder({
        email: value,
        currency,
        returnUrl,
      });
      if (data.mode === 'mock') {
        setMockNote(data.note || t.preorder.mockHint);
        setStatus('mock');
        return;
      }
      if (!data.payment_html) {
        setMockNote(data.note || t.preorder.mockHint);
        setStatus('mock');
        return;
      }
      setPaymentHtml(data.payment_html);
      setStatus('redirecting');
    } catch (e) {
      setErrorMsg(e instanceof Error ? e.message : String(e));
      setStatus('error');
    }
  };

  const manualSubmit = () => {
    const form = formSlotRef.current?.querySelector('form');
    if (form instanceof HTMLFormElement) form.submit();
  };

  const showActionButton = status === 'idle' || status === 'submitting' || status === 'error';

  return (
    <PaymentLayout>
      <div className="preorder">
        <span className="preorder__badge">{t.preorder.badge}</span>
        <h1 className="preorder__title">{t.preorder.title}</h1>
        <p className="preorder__subtitle">{t.preorder.subtitle}</p>

        <div className="preorder__currencies" role="radiogroup" aria-label={t.preorder.title}>
          <button
            type="button"
            role="radio"
            aria-checked={currency === 'CNY'}
            className={`preorder__currency ${currency === 'CNY' ? 'is-active' : ''}`}
            onClick={() => setCurrency('CNY')}
            disabled={status !== 'idle'}
          >
            <span className="preorder__currency-label">{t.preorder.currencyRmb}</span>
            <span className="preorder__currency-price">
              {currentPrice.cny != null ? `¥${currentPrice.cny}` : t.preorder.rmbPrice}
            </span>
            <span className="preorder__currency-original">{t.preorder.rmbOriginal}</span>
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={currency === 'USD'}
            className={`preorder__currency ${currency === 'USD' ? 'is-active' : ''}`}
            onClick={() => setCurrency('USD')}
            disabled={status !== 'idle'}
          >
            <span className="preorder__currency-label">{t.preorder.currencyUsd}</span>
            <span className="preorder__currency-price">
              {currentPrice.usd != null ? `$${currentPrice.usd}` : t.preorder.usdPrice}
            </span>
            <span className="preorder__currency-original">{t.preorder.usdOriginal}</span>
          </button>
        </div>

        <div className="preorder__features">
          <p className="preorder__features-title">{t.preorder.featuresTitle}</p>
          <ul>
            <li>{t.preorder.f1}</li>
            <li>{t.preorder.f2}</li>
            <li>{t.preorder.f3}</li>
          </ul>
        </div>

        <div className="preorder__field">
          <label className="preorder__label" htmlFor="pay-email">
            {t.preorder.emailLabel}
          </label>
          <input
            id="pay-email"
            type="email"
            autoComplete="email"
            className={`preorder__input ${emailError ? 'is-error' : ''}`}
            placeholder={t.preorder.emailPlaceholder}
            value={email}
            onChange={(e) => {
              const value = e.target.value.replace(/。/g, '.');
              setEmail(value);
              if (emailError) setEmailError(null);
            }}
            onBlur={() => {
              if (email.trim() && !EMAIL_RE.test(email.trim())) {
                setEmailError(t.preorder.emailInvalid);
              }
            }}
          />
          {emailError ? (
            <p className="preorder__field-error" role="alert">
              {emailError}
            </p>
          ) : (
            <p className="preorder__field-hint">{t.preorder.emailHint}</p>
          )}
        </div>

        {showActionButton && (
          <button
            type="button"
            className="preorder__submit"
            onClick={handleSubmit}
            disabled={status === 'submitting'}
          >
            {status === 'submitting' ? t.preorder.submitting : t.preorder.submit}
          </button>
        )}

        <Link
          className="preorder__query-link"
          to={`/query_pro${email.trim() ? `?email=${encodeURIComponent(email.trim())}` : ''}`}
        >
          {t.preorder.queryLicense}
        </Link>

        {status === 'error' && (
          <div className="preorder__notice is-error" role="alert">
            <p className="preorder__notice-title">{t.preorder.errorTitle}</p>
            <p className="preorder__notice-text">{errorMsg}</p>
          </div>
        )}

        {status === 'mock' && (
          <div className="preorder__notice" role="status">
            <p className="preorder__notice-title">{t.preorder.mockTitle}</p>
            <p className="preorder__notice-text">{mockNote}</p>
          </div>
        )}

        {status === 'redirecting' && (
          <div className="preorder__redirect" role="status">
            <span className="preorder__spinner" aria-hidden="true" />
            <p className="preorder__redirect-title">{t.preorder.redirecting}</p>
            <p className="preorder__redirect-hint">{t.preorder.redirectHint}</p>
            <button type="button" className="preorder__manual" onClick={manualSubmit}>
              {t.preorder.manualRedirect}
            </button>
            <div ref={formSlotRef} className="preorder__form-slot" />
          </div>
        )}

        {status === 'paddle_open' && (
          <div className="preorder__redirect" role="status">
            <span className="preorder__spinner" aria-hidden="true" />
            <p className="preorder__redirect-title">{t.preorder.paddleOpening}</p>
            <p className="preorder__redirect-hint">{t.preorder.paddleOpenHint}</p>
            <button
              type="button"
              className="preorder__manual"
              onClick={() => {
                clearPaddleCallbacks();
                setStatus('idle');
              }}
            >
              {t.preorder.paddleBack}
            </button>
          </div>
        )}
      </div>
    </PaymentLayout>
  );
}