export type OS = 'macos' | 'windows' | 'linux' | 'unknown';
export type Arch = 'arm64' | 'x64' | 'unknown';

export interface DownloadItem {
  id: string;
  arch: string;
  filename: string;
  size: string;
  href: string;
  format: string;
}

export interface Platform {
  os: OS;
  label: string;
  icon: 'macos' | 'windows' | 'linux';
  downloads: DownloadItem[];
}

export function detectOS(): OS {
  const ua = navigator.userAgent.toLowerCase();
  if (ua.includes('mac os') || ua.includes('macos') || ua.includes('darwin')) {
    return 'macos';
  }
  if (ua.includes('windows') || ua.includes('win32')) {
    return 'windows';
  }
  if (ua.includes('linux') || ua.includes('x11') || ua.includes('ubuntu')) {
    return 'linux';
  }
  return 'unknown';
}

export function detectArch(): Arch {
  const platform = navigator.platform.toLowerCase();
  const ua = navigator.userAgent.toLowerCase();

  if (ua.includes('arm64') || ua.includes('aarch64') || platform.includes('arm')) {
    return 'arm64';
  }
  if (ua.includes('x64') || ua.includes('amd64') || ua.includes('x86_64') || ua.includes('win64')) {
    return 'x64';
  }
  return 'unknown';
}

