import { useHeaderShadow } from '../hooks/useScrollReveal';
import { useI18n } from '../i18n';
import { Link } from 'react-router-dom';
import './Header.css';

export default function Header() {
  const scrolled = useHeaderShadow();
  const { t, locale, toggleLocale } = useI18n();

  const scrollToDownload = (e: React.MouseEvent) => {
    e.preventDefault();
    const el = document.getElementById('download');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className={`header ${scrolled ? 'header--scrolled' : ''}`}>
      <div className="header__inner container">
        <div className="header__brand">
          <svg
            className="header__logo"
            width="20"
            height="20"
            viewBox="0 0 32 32"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <rect x="2" y="2" width="28" height="28" rx="6" stroke="currentColor" strokeWidth="2" fill="none" />
            <rect x="8" y="10" width="16" height="3" rx="1.5" fill="currentColor" />
            <rect x="8" y="16" width="12" height="3" rx="1.5" fill="currentColor" />
            <rect x="8" y="22" width="8" height="3" rx="1.5" fill="currentColor" />
          </svg>
          <span className="header__name">Coco Toast</span>
        </div>

        <nav className="header__nav">
          <button
            type="button"
            className="header__lang-btn"
            onClick={toggleLocale}
            aria-label={t.language.switch}
            title={t.language.switch}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="10" />
              <path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
            </svg>
            <span className="header__lang-label">
              {locale === 'zh-CN' ? t.language.en : t.language.zh}
            </span>
          </button>
          <Link to="/buy_pro" className="header__buy-btn">
            {t.header.buy}
          </Link>
          <a
            href="#download"
            className="header__download-btn"
            onClick={scrollToDownload}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3" />
            </svg>
            {t.header.download}
          </a>
        </nav>
      </div>
    </header>
  );
}
