// Paddle.js 客户端集成：负责初始化与打开 Checkout overlay。
// 仅用于美元（USD）一次性买断授权，环境与 token 全部从环境变量读取，绝不硬编码。

import {
  initializePaddle,
  type Paddle,
  type Environments,
  type CheckoutEventsData,
  type CheckoutEventError,
  CheckoutEventNames,
} from '@paddle/paddle-js';

const PADDLE_ENV = import.meta.env.VITE_PADDLE_ENV as string | undefined;
const PADDLE_TOKEN = import.meta.env.VITE_PADDLE_CLIENT_TOKEN as string | undefined;
const PADDLE_PRICE_ID = import.meta.env.VITE_PADDLE_PRICE_ID as string | undefined;

/**
 * 当前 Checkout 的回调集合。eventCallback 在 initializePaddle 时一次性注册，
 * 之后每次 Checkout.open 复用同一个全局回调，因此用模块级变量做中转。
 */
type CheckoutCallbacks = {
  onCompleted?: (data: CheckoutEventsData) => void;
  onClosed?: () => void;
  onError?: (error: CheckoutEventError) => void;
};

let currentCallbacks: CheckoutCallbacks | null = null;
let initPromise: Promise<Paddle | null> | null = null;

function resolveEnv(): { env: Environments; token: string; priceId: string } {
  if (PADDLE_ENV !== 'sandbox' && PADDLE_ENV !== 'production') {
    throw new Error(
      `VITE_PADDLE_ENV 必须为 "sandbox" 或 "production"（当前: ${PADDLE_ENV ?? '未设置'}）`,
    );
  }
  if (!PADDLE_TOKEN) {
    throw new Error('VITE_PADDLE_CLIENT_TOKEN 未设置（sandbox token 以 test_ 前缀开头）');
  }
  if (!PADDLE_PRICE_ID) {
    throw new Error('VITE_PADDLE_PRICE_ID 未设置（在 Paddle 控制台创建产品/价格后复制 pri_ 开头的 ID）');
  }
  return { env: PADDLE_ENV, token: PADDLE_TOKEN, priceId: PADDLE_PRICE_ID };
}

/** 是否已配置 Paddle 必要环境变量。用于前端判断是否可走 Paddle 通道。 */
export function isPaddleConfigured(): boolean {
  return Boolean(
    (PADDLE_ENV === 'sandbox' || PADDLE_ENV === 'production') && PADDLE_TOKEN && PADDLE_PRICE_ID,
  );
}

export function getPaddleEnvironment(): 'sandbox' | 'production' | null {
  if (PADDLE_ENV === 'sandbox' || PADDLE_ENV === 'production') return PADDLE_ENV;
  return null;
}

/**
 * 单例初始化 Paddle.js。多次调用安全（返回同一个 Promise）。
 * eventCallback 在此设置，后续所有 Checkout.open 共用。
 */
export function initPaddle(): Promise<Paddle | null> {
  if (initPromise) return initPromise;
  initPromise = (async () => {
    const { env, token } = resolveEnv();
    const paddle = await initializePaddle({
      token,
      environment: env,
      eventCallback: (event) => {
        if (!event.name) return;
        const cb = currentCallbacks;
        if (!cb) return;
        switch (event.name) {
          case CheckoutEventNames.CHECKOUT_COMPLETED:
            if (event.data) cb.onCompleted?.(event.data);
            break;
          case CheckoutEventNames.CHECKOUT_CLOSED:
            cb.onClosed?.();
            break;
          case CheckoutEventNames.CHECKOUT_ERROR:
          case CheckoutEventNames.CHECKOUT_PAYMENT_ERROR:
            cb.onError?.(event as CheckoutEventError);
            break;
        }
      },
    });
    return paddle ?? null;
  })();
  return initPromise;
}

export interface OpenPaddleCheckoutParams {
  /** 用户邮箱，用于预填 Checkout */
  email: string;
  /** 支付成功后跳转地址；调用方需在 onCompleted 里自行跳转，函数不再自动拼接 */
  onCompleted?: (data: CheckoutEventsData) => void;
  onClosed?: () => void;
  onError?: (error: CheckoutEventError) => void;
}

/**
 * 打开 Paddle Checkout overlay（单页模式）。
 * - items 取自 VITE_PADDLE_PRICE_ID，quantity 固定 1（一次性买断）。
 * - 不再传 custom_data.order_id：前端不预先下单，Paddle 不感知本地订单 ID；
 *   Paddle 会在 checkout.completed 事件 data.transaction_id 里回传交易 ID
 *   (txn_ 前缀)，由调用方在 onCompleted 中拿到后跳转 /pay/result。
 */
export async function openPaddleCheckout(params: OpenPaddleCheckoutParams): Promise<void> {
  const paddle = await initPaddle();
  if (!paddle) {
    throw new Error('Paddle 初始化失败，请检查 VITE_PADDLE_CLIENT_TOKEN 与 VITE_PADDLE_ENV 配置');
  }
  const { priceId } = resolveEnv();
  currentCallbacks = {
    onCompleted: params.onCompleted,
    onClosed: params.onClosed,
    onError: params.onError,
  };
  paddle.Checkout.open({
    items: [{ priceId, quantity: 1 }],
    customer: { email: params.email },
    settings: {
      displayMode: 'overlay',
      variant: 'one-page',
    },
  });
}

/** 清理当前 Checkout 的回调（应在 onClosed/onError 后调用，避免泄漏到下一次）。 */
export function clearPaddleCallbacks(): void {
  currentCallbacks = null;
}
