// 支付相关 API 客户端：封装预购下单与订单状态查询。
// 基址默认指向 Coco Toast 服务器，可在构建时用 VITE_API_BASE_URL 覆盖。

export type Currency = "CNY" | "USD";

/** 支付通道：CNY 走 alipay，USD 走 paddle（由前端按币种决定，服务端据此下单） */
export type PaymentChannel = "alipay" | "paddle";

export interface PreorderData {
  order_id: string;
  amount: string;
  currency: Currency;
  email: string;
  expires_at: number;
  payment_channel: string;
  mode: "mock" | "sandbox" | "live";
  /** alipay.trade.page.pay 生成的自动提交表单 HTML；mock / paddle 模式下为 null */
  payment_html: string | null;
  note?: string;
}

export type OrderStatusValue = "pending" | "paid" | "expired";

export interface OrderStatus {
  order_id: string;
  status: OrderStatusValue;
  amount: string | null;
  currency: string | null;
  email: string | null;
  license_code: string | null;
  paid_at: number | null;
  expired_at: number | null;
  license: {
    license_code: string;
    status: string;
    max_activations: number;
    used_count: number;
  } | null;
}

const API_BASE_URL =
  (import.meta.env.VITE_API_BASE_URL as string | undefined) ||
  "https://appserver.coconot.cc";

/**
 * 购买页“当前价”。服务端返回两个币种的当前售价（不含货币符号），
 * 前端负责拼 ¥ / $ 显示。USD 从 Paddle 取并缓存 1 小时；CNY 来自服务器 env。
 * 原价不在此接口，仍由前端 i18n 展示。
 */
export interface CurrentPriceData {
  cny: { amount: string; currency: "CNY" };
  usd: {
    amount: string | null;
    currency: "USD";
    /** USD 金额来源：cache=KV 缓存命中 / paddle=本次实时取 / none=Paddle 未配置或失败 */
    source: "cache" | "paddle" | "none";
  };
}

/** 获取购买页“当前价”（GET /api/order/price）。请求失败时抛错，由调用方兜底回退。 */
export async function fetchPrices(): Promise<CurrentPriceData> {
  const res = await fetch(`${API_BASE_URL}/api/order/price`);
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    data?: CurrentPriceData;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(`获取价格失败 (HTTP ${res.status})`);
  }
  return body.data;
}

/**
 * 创建预购订单（仅传 email + currency + channel，金额由服务器按默认价结算）。
 * - CNY 默认走 alipay，返回 payment_html（自动提交表单）。
 * - USD 走 paddle，payment_html 为 null，前端用 Paddle.Checkout.open 完成付款。
 * 返回服务器 data 字段；请求失败或 success=false 时抛错。
 */
export async function createPreorder({
  email,
  currency,
  returnUrl,
  channel,
}: {
  email: string;
  currency: Currency;
  /** 支付成功后的同步回跳地址（如官网 /pay/result），传给服务器设定 return_url */
  returnUrl?: string;
  /** 支付通道：默认按币种自动选择（CNY=alipay, USD=paddle），可显式覆盖 */
  channel?: PaymentChannel;
}): Promise<PreorderData> {
  const resolvedChannel: PaymentChannel =
    channel ?? (currency === "USD" ? "paddle" : "alipay");
  const res = await fetch(`${API_BASE_URL}/api/order/create`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email,
      product: "cocotoast_license",
      channel: resolvedChannel,
      currency,
      ...(returnUrl ? { return_url: returnUrl } : {}),
    }),
  });
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    message?: string;
    data?: PreorderData;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(body?.message || `预购请求失败 (HTTP ${res.status})`);
  }
  return body.data;
}

/** 订单不存在时抛此错误，便于调用方区分 404。 */
export class OrderNotFoundError extends Error {
  constructor() {
    super("ORDER_NOT_FOUND");
    this.name = "OrderNotFoundError";
  }
}

/** 按邮箱查询激活码发送状态 */
export type QueryProFound = "license" | "orders" | "none";

/** 单个授权码的概要信息（license_code 已由服务端脱敏为前 3 位 + *** + 后 3 位） */
export interface QueryProLicenseItem {
  license_code: string;
  status: string;
  expires_at: number | null;
  max_activations: number;
  used_count: number;
}

export interface QueryProLicense {
  found: "license";
  email: string;
  /** 同一邮箱可能购买多次，返回全部有效授权 */
  licenses: QueryProLicenseItem[];
  query_link?: string;
}

export interface QueryProOrder {
  order_id: string;
  status: string;
  amount: string;
  currency: string;
  created_at: number;
  expired_at: number | null;
}

export interface QueryProOrders {
  found: "orders";
  email: string;
  orders: QueryProOrder[];
}

export interface QueryProNone {
  found: "none";
  email: string;
  orders: [];
}

export type QueryProResult = QueryProLicense | QueryProOrders | QueryProNone;

/**
 * 按邮箱查询激活码（POST /api/querypro）。
 * 返回服务器 data 字段；请求失败或 success=false 时抛错。
 */
export async function queryPro(email: string): Promise<QueryProResult> {
  const res = await fetch(`${API_BASE_URL}/api/querypro`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email }),
  });
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    message?: string;
    data?: QueryProResult;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(body?.message || `查询失败 (HTTP ${res.status})`);
  }
  return body.data;
}

export interface QueryTokenDevice {
  name: string;
  activated_at: number;
  activation_id: number;
}
export interface QueryTokenLicense {
  license_code: string;
  status: string;
  max_activations: number;
  used_count: number;
  expires_at: number | null;
  devices: QueryTokenDevice[];
}
export interface QueryTokenResult {
  email: string;
  licenses: QueryTokenLicense[];
  /** 90 分钟有效的 JWT，用于撤销激活；应仅在内存保留，勿持久化 */
  management_token?: string | null;
}
export class QueryTokenInvalidError extends Error {
  constructor() {
    super("QUERY_TOKEN_INVALID");
    this.name = "QueryTokenInvalidError";
  }
}

/** 按查询令牌查询授权详情（POST /api/querypro，token 分支）。 */
export async function queryToken(token: string): Promise<QueryTokenResult> {
  const res = await fetch(`${API_BASE_URL}/api/querypro`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ token }),
  });
  if (res.status === 404) {
    throw new QueryTokenInvalidError();
  }
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    data?: QueryTokenResult;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(`查询失败 (HTTP ${res.status})`);
  }
  return body.data;
}

/** 撤销指定设备的激活（POST /api/activate/revoke，JWT 鉴权）。 */
export async function revokeActivation({
  activationId,
  jwt,
}: {
  activationId: number;
  jwt: string;
}): Promise<void> {
  const res = await fetch(`${API_BASE_URL}/api/activate/revoke`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${jwt}`,
    },
    body: JSON.stringify({ activation_id: activationId }),
  });
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    message?: string;
  } | null;
  if (!res.ok || !body?.success) {
    throw new Error(body?.message || `撤销失败 (HTTP ${res.status})`);
  }
}

/**
 * 查询订单状态（GET /api/order/:orderId）。
 *
 * 对于 paddle 通道，orderId 实际是 Paddle 的 transaction_id（txn_ 前缀）。
 * 此时传 ?payment_channel=paddle 让服务端按需调 Paddle API 同步状态。
 */
export async function fetchOrder(
  orderId: string,
  opts?: { channel?: PaymentChannel },
): Promise<OrderStatus> {
  const qs = opts?.channel
    ? `?payment_channel=${encodeURIComponent(opts.channel)}`
    : "";
  const res = await fetch(
    `${API_BASE_URL}/api/order/${encodeURIComponent(orderId)}${qs}`,
  );
  if (res.status === 404) {
    throw new OrderNotFoundError();
  }
  if (!res.ok) {
    throw new Error(`查询订单失败 (HTTP ${res.status})`);
  }
  const body = (await res.json().catch(() => null)) as OrderStatus | null;
  if (!body) {
    throw new Error("订单响应解析失败");
  }
  return body;
}
