import { useEffect, useState } from 'react';
import { Routes, Route, useNavigate, useLocation, Link } from 'react-router-dom';
import { useI18n, format } from './i18n';
import LandingPage from './pages/LandingPage';
import PreorderPage from './pages/PreorderPage';
import ProQueryPage from './pages/ProQueryPage';
import PayReturnPage from './pages/PayReturnPage';
import './styles/variables.css';
import './styles/base.css';
import './styles/animations.css';
import './components/Header.css';
import './components/Hero.css';
import './components/Features.css';
import './components/FeatureShowcase.css';
import './components/Download.css';
import './components/Footer.css';

const NOT_FOUND_REDIRECT_SECONDS = 3;

function NotFound() {
  const { t } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const [seconds, setSeconds] = useState(NOT_FOUND_REDIRECT_SECONDS);

  useEffect(() => {
    const id = setInterval(() => {
      setSeconds((prev) => {
        if (prev <= 1) {
          clearInterval(id);
          navigate('/', { replace: true });
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, [navigate]);

  return (
    <main
      style={{
        minHeight: 'calc(100vh - var(--header-height, 64px))',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '0.75rem',
        padding: '2rem',
        textAlign: 'center',
      }}
    >
      <div
        style={{
          fontFamily: 'var(--font-heading)',
          fontSize: '5rem',
          fontWeight: 700,
          lineHeight: 1,
          color: 'var(--color-accent)',
        }}
      >
        {t.notFound.title}
      </div>
      <p style={{ fontSize: '1rem', color: 'var(--color-text)' }}>
        {t.notFound.message}
      </p>
      <p style={{ fontSize: '0.875rem', color: 'var(--color-text-muted)' }}>
        {format(t.notFound.redirecting, { seconds: String(seconds) })}
      </p>
      <p
        style={{
          fontSize: '0.8rem',
          color: 'var(--color-text-muted)',
          wordBreak: 'break-all',
          opacity: 0.7,
        }}
      >
        {location.pathname}
      </p>
      <Link
        to="/"
        style={{
          marginTop: '0.5rem',
          padding: '0.5rem 1.25rem',
          border: '1px solid var(--color-border)',
          borderRadius: 'var(--radius-sm)',
          color: 'var(--color-text)',
        }}
      >
        {t.notFound.back}
      </Link>
    </main>
  );
}

export default function App() {
  return (
    <Routes>
      <Route path="/" element={<LandingPage />} />
      <Route path="/buy_pro" element={<PreorderPage />} />
      <Route path="/query_pro" element={<ProQueryPage />} />
      <Route path="/pay/result" element={<PayReturnPage />} />
      <Route path="*" element={<NotFound />} />
    </Routes>
  );
}
