import { useState, useEffect, useRef, useCallback } from 'react';
import { useI18n } from '../i18n';
import './FeatureShowcase.css';

interface FeatureItem {
  label: string;
  type: string;
  displayContent: string;
  rawContent?: string;
  isLong?: boolean;
}

const ANIM_DURATION = 350;

export default function FeatureShowcase() {
  const { t } = useI18n();
  const [activeIndex, setActiveIndex] = useState(0);
  const [anim, setAnim] = useState<'entering' | 'visible' | 'leaving'>('entering');
  const [isPaused, setIsPaused] = useState(false);
  const [progressKey, setProgressKey] = useState(0);
  const transitionRef = useRef<ReturnType<typeof setTimeout>>();

  const FEATURES: FeatureItem[] = [
    {
      label: t.showcase.items.timestamp.label,
      type: t.showcase.items.timestamp.type,
      displayContent: '2024/12/21 14:30:00',
      rawContent: '1734777000',
    },
    {
      label: t.showcase.items.unicode.label,
      type: t.showcase.items.unicode.type,
      displayContent: '你好，世界！',
      rawContent: '\\u4f60\\u597d\\uff0c\\u4e16\\u754c\\uff01',
    },
    {
      label: t.showcase.items.hex.label,
      type: t.showcase.items.hex.type,
      displayContent: 'Hello',
      rawContent: '48656C6C6F',
    },
    {
      label: t.showcase.items.json.label,
      type: t.showcase.items.json.type,
      displayContent: `{\n  "name": "Alice",\n  "age": 28,\n  "role": "developer"\n}`,
      rawContent: '{"name":"Alice","age":28,"role":"developer"}',
      isLong: true,
    },
    {
      label: t.showcase.items.email.label,
      type: t.showcase.items.email.type,
      displayContent: '847291',
    },
  ];

  const cancelTransitions = useCallback(() => {
    clearTimeout(transitionRef.current);
  }, []);

  const switchTo = useCallback((index: number) => {
    cancelTransitions();
    setAnim('leaving');

    transitionRef.current = setTimeout(() => {
      setActiveIndex(index);
      setAnim('entering');

      transitionRef.current = setTimeout(() => {
        setAnim('visible');
      }, ANIM_DURATION);
    }, ANIM_DURATION);
  }, [cancelTransitions]);

  useEffect(() => {
    if (anim === 'visible') {
      setProgressKey(k => k + 1);
    }
  }, [anim]);

  useEffect(() => {
    const timer = setTimeout(() => setAnim('visible'), ANIM_DURATION);
    return () => clearTimeout(timer);
  }, []);

  const handleItemHover = (index: number) => {
    if (index === activeIndex) {
      cancelTransitions();
      setAnim('visible');
      return;
    }
    switchTo(index);
  };

  const handlePopupEnter = () => setIsPaused(true);
  const handlePopupLeave = () => setIsPaused(false);

  const handleProgressEnd = useCallback(() => {
    switchTo((activeIndex + 1) % FEATURES.length);
  }, [activeIndex, switchTo, FEATURES.length]);

  const isOtp = activeIndex === 4;
  const feat = FEATURES[activeIndex];

  return (
    <section className="features-demo" id="features-demo">
      <div className="container">
        <div className="features-demo__header">
          <h2 className="features-demo__title">{t.showcase.title}</h2>
          <p className="features-demo__subtitle">{t.showcase.subtitle}</p>
        </div>
        <div className="features-demo__inner">
          <div className="features-demo__list">
            {FEATURES.map((f, i) => (
              <div
                key={f.label}
                className={`features-demo__item ${i === activeIndex ? 'features-demo__item--active' : ''}`}
                onMouseEnter={() => handleItemHover(i)}
              >
                <span className="features-demo__item-index">
                  {(i + 1).toString().padStart(2, '0')}
                </span>
                <span className="features-demo__item-text">{f.label}</span>
              </div>
            ))}
          </div>
          <div className="features-demo__stage">
            <div
              className={`fd-popup fd-popup--${anim}`}
              onMouseEnter={handlePopupEnter}
              onMouseLeave={handlePopupLeave}
            >
              <div className="fd-popup__btn-group">
                <button className="fd-popup__btn fd-popup__btn--close">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
                    <path d="M9 9L11.9999 11.9999M11.9999 11.9999L14.9999 14.9999M11.9999 11.9999L9 14.9999M11.9999 11.9999L14.9999 9M4 16.8002V7.2002C4 6.08009 4 5.51962 4.21799 5.0918C4.40973 4.71547 4.71547 4.40973 5.0918 4.21799C5.51962 4 6.08009 4 7.2002 4H16.8002C17.9203 4 18.4801 4 18.9079 4.21799C19.2842 4.40973 19.5905 4.71547 19.7822 5.0918C20.0002 5.51962 20.0002 6.07967 20.0002 7.19978V16.7998C20.0002 17.9199 20.0002 18.48 19.7822 18.9078C19.5905 19.2841 19.2842 19.5905 18.9079 19.7822C18.4805 20 17.9215 20 16.8036 20H7.19691C6.07899 20 5.5192 20 5.0918 19.7822C4.71547 19.5905 4.40973 19.2842 4.21799 18.9079C4 18.4801 4 17.9203 4 16.8002Z" />
                  </svg>
                </button>
                <button className="fd-popup__btn">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
                    <path d="M9 9V6.2002C9 5.08009 9 4.51962 9.21799 4.0918C9.40973 3.71547 9.71547 3.40973 10.0918 3.21799C10.5196 3 11.0801 3 12.2002 3H17.8002C18.9203 3 19.4801 3 19.9079 3.21799C20.2842 3.40973 20.5905 3.71547 20.7822 4.0918C21.0002 4.51962 21.0002 5.07967 21.0002 6.19978V11.7998C21.0002 12.9199 21.0002 13.48 20.7822 13.9078C20.5905 14.2841 20.2839 14.5905 19.9076 14.7822C19.4802 15 18.921 15 17.8031 15H15M9 9H6.2002C5.08009 9 4.51962 9 4.0918 9.21799C3.71547 9.40973 3.40973 9.71547 3.21799 10.0918C3 10.5196 3 11.0801 3 12.2002V17.8002C3 18.9203 3 19.4801 3.21799 19.9079C3.40973 20.2842 3.71547 20.5905 4.0918 20.7822C4.5192 21 5.07899 21 6.19691 21H11.8036C12.9215 21 13.4805 21 13.9079 20.7822C14.2842 20.5905 14.5905 20.2839 14.7822 19.9076C15 19.4802 15 18.921 15 17.8031V15M9 9H11.8002C12.9203 9 13.4801 9 13.9079 9.21799C14.2842 9.40973 14.5905 9.71547 14.7822 10.0918C15 10.5192 15 11.079 15 12.1969L15 15" />
                  </svg>
                </button>
              </div>
              <div className={`fd-popup__label ${isOtp ? 'fd-popup__label--otp' : ''}`}>
                {feat.type}
              </div>
              <div className={`fd-popup__body ${isOtp ? 'fd-popup__body--otp' : 'fd-popup__body--top'}`}>
                {isOtp ? (
                  <span className="fd-popup__otp">{feat.displayContent}</span>
                ) : (
                  <>
                    {feat.isLong ? (
                      <pre className="fd-popup__main fd-popup__main--long">{feat.displayContent}</pre>
                    ) : (
                      <span className="fd-popup__main">{feat.displayContent}</span>
                    )}
                    <span className="fd-popup__raw">{feat.rawContent}</span>
                  </>
                )}
              </div>
              <div
                key={progressKey}
                className={`fd-popup__progress ${isPaused ? 'is-paused' : ''}`}
                onAnimationEnd={handleProgressEnd}
              >
                <div className="fd-popup__progress-bar" />
              </div>
            </div>
          </div>
        </div>
        <p className="features-demo__footer">{t.showcase.footer}</p>
      </div>
    </section>
  );
}
