import { useCallback, useEffect, useRef, useState } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { useI18n, format } from '../i18n';
import {
  queryPro,
  queryToken,
  revokeActivation,
  QueryTokenInvalidError,
  type QueryProLicenseItem,
  type QueryProResult,
  type QueryTokenDevice,
  type QueryTokenLicense,
  type QueryTokenResult,
} from '../lib/paymentApi';
import PaymentLayout from '../components/PaymentLayout';
import './ProQueryPage.css';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Status = 'idle' | 'submitting' | 'license' | 'orders' | 'none' | 'error';
type TokenStatus = 'token-loading' | 'token-ok' | 'token-invalid' | null;

function LicenseResults({
  licenses,
  withDevices = false,
  showHint = true,
  onRevoke,
}: {
  licenses: QueryProLicenseItem[] | QueryTokenLicense[];
  withDevices?: boolean;
  /** 是否显示「已发送到邮箱」提示；仅 email 查询成功时展示，token 查询不展示 */
  showHint?: boolean;
  onRevoke?: (device: QueryTokenDevice) => void;
}) {
  const { t } = useI18n();
  return (
    <div className="proquery__result" role="status">
      <p className="proquery__result-title">{t.proQuery.licenseFoundTitle}</p>
      <div className="proquery__orders">
        {licenses.map((lic, i) => (
          <div className="proquery__order" key={i}>
            <div className="proquery__order-head">
              <span className="proquery__order-label">
                {t.proQuery.licenseCodeLabel}:{' '}
                <code className="proquery__order-value">{lic.license_code}</code>
              </span>
              {'max_activations' in lic && lic.max_activations != null && (
                <span className="proquery__used-count">
                  {t.proQuery.usedCountLabel} {lic.used_count}/{lic.max_activations}
                </span>
              )}
            </div>
            {withDevices &&
              'devices' in lic &&
              lic.devices.length > 0 && (
                <div className="proquery__devices">
                  <h4 className="proquery__devices-title">
                    {t.proQuery.devicesTitle}
                  </h4>
                  {lic.devices.map((dev, j) => (
                    <div className="proquery__device" key={j}>
                      <div className="proquery__device-row">
                        <div className="proquery__device-info">
                          <div className="proquery__device-name">
                            {t.proQuery.deviceLabel}: {dev.name}
                          </div>
                          <div className="proquery__device-time">
                            {t.proQuery.activatedAtLabel}:{' '}
                            {new Date(dev.activated_at * 1000).toLocaleString()}
                          </div>
                        </div>
                        {onRevoke && (
                          <button
                            type="button"
                            className="proquery__revoke-btn"
                            onClick={() => onRevoke(dev)}
                          >
                            {t.proQuery.revokeDevice}
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
          </div>
        ))}
      </div>
      {showHint && (
        <p className="proquery__result-hint">{t.proQuery.licenseFoundHint}</p>
      )}
    </div>
  );
}

export default function ProQueryPage() {
  const { t } = useI18n();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();

  const initialEmail = searchParams.get('email') ?? '';
  const queryTokenParam = searchParams.get('query_token');
  const [email, setEmail] = useState(initialEmail);
  const [emailError, setEmailError] = useState<string | null>(null);
  const [status, setStatus] = useState<Status>('idle');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [result, setResult] = useState<QueryProResult | null>(null);
  const [tokenStatus, setTokenStatus] = useState<TokenStatus>(null);
  const [tokenResult, setTokenResult] = useState<QueryTokenResult | null>(null);

  // JWT 仅保存在内存变量中，用于撤销激活时鉴权，不持久化到 storage
  const [jwtToken, setJwtToken] = useState<string | null>(null);
  const [revokeTarget, setRevokeTarget] = useState<QueryTokenDevice | null>(null);
  const [revoking, setRevoking] = useState(false);
  const [revokeError, setRevokeError] = useState<string | null>(null);

  const autoTriggeredRef = useRef(false);
  const tokenFiredRef = useRef(false);

  // 查询逻辑：传入待查询邮箱，缺省时使用当前输入框的值
  const handleQuery = useCallback(
    async (value?: string) => {
      const emailToUse = (value ?? email).trim();
      if (!EMAIL_RE.test(emailToUse)) {
        setEmailError(t.proQuery.emailInvalid);
        return;
      }
      setEmailError(null);
      setStatus('submitting');
      setErrorMsg(null);
      try {
        const data = await queryPro(emailToUse);
        setResult(data);
        setStatus(data.found === 'license' ? 'license' : data.found === 'orders' ? 'orders' : 'none');
      } catch (e) {
        setStatus('error');
        setErrorMsg(e instanceof Error ? e.message : String(e));
      }
    },
    [email, t.proQuery.emailInvalid],
  );

  // 携带邮箱参数进入页面时，延迟 2 秒自动触发一次查询
  useEffect(() => {
    if (queryTokenParam) return;
    if (!initialEmail || autoTriggeredRef.current) return;
    autoTriggeredRef.current = true;
    const timer = setTimeout(() => {
      handleQuery(initialEmail);
    }, 2000);
    return () => clearTimeout(timer);
  }, [initialEmail, handleQuery, queryTokenParam]);

  // 查询令牌模式：携带 query_token 参数时自动查询授权详情。
  // 用 ref 去重，避免 React StrictMode 下 effect 双调用导致请求发两次。
  useEffect(() => {
    if (!queryTokenParam || tokenFiredRef.current) return;
    tokenFiredRef.current = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    setTokenStatus('token-loading');
    queryToken(queryTokenParam)
      .then((data) => {
        setTokenResult(data);
        setJwtToken(data.management_token ?? null);
        setTokenStatus('token-ok');
        setStatus('license')
      })
      .catch((e) => {
        if (e instanceof QueryTokenInvalidError) {
          setTokenStatus('token-invalid');
          timer = setTimeout(
            () => navigate('/query_pro', { replace: true }),
            2000,
          );
        }
      });
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [queryTokenParam, navigate]);

  const handleEmailChange = (value: string) => {
    setEmail(value);
    if (emailError) setEmailError(null);
  };

  const handleRevokeClick = (device: QueryTokenDevice) => {
    setRevokeError(null);
    setRevokeTarget(device);
  };

  const confirmRevoke = async () => {
    if (!revokeTarget || !jwtToken) return;
    setRevoking(true);
    setRevokeError(null);
    try {
      await revokeActivation({
        activationId: revokeTarget.activation_id,
        jwt: jwtToken,
      });
      // 撤销成功后丢弃内存中的 JWT，并刷新页面重新拉取设备列表
      setJwtToken(null);
      setRevokeTarget(null);
      window.location.reload();
    } catch (e) {
      setRevokeError(e instanceof Error ? e.message : String(e));
      setRevoking(false);
    }
  };

  const isTokenMode = tokenStatus !== null;
  const inputEmail = isTokenMode ? (tokenResult?.email ?? '') : email;
  const firstQueryLink =
    status === 'license' && result?.found === 'license'
      ? result.query_link
      : undefined;

  return (
    <PaymentLayout>
      <div className="proquery">
        <h1 className="proquery__title">{t.proQuery.title}</h1>
        <p className="proquery__subtitle">{t.proQuery.subtitle}</p>

        <div className="proquery__field">
          <label className="proquery__label" htmlFor="proquery-email">
            {t.proQuery.emailLabel}
          </label>
          <input
            id="proquery-email"
            type="email"
            autoComplete="email"
            className={`proquery__input ${emailError ? 'is-error' : ''}`}
            placeholder={t.proQuery.emailPlaceholder}
            value={inputEmail}
            readOnly={isTokenMode}
            onChange={(e) => handleEmailChange(e.target.value)}
            onBlur={() => {
              if (email.trim() && !EMAIL_RE.test(email.trim())) {
                setEmailError(t.proQuery.emailInvalid);
              }
            }}
          />
          {emailError ? (
            <p className="proquery__field-error" role="alert">
              {emailError}
            </p>
          ) : status !== "orders" && status !== "license" ? ( 
            <p className="proquery__field-hint">{t.proQuery.emailHint}</p>
          ) : null}
        </div>

        {!isTokenMode && (
          <button
            type="button"
            className="proquery__submit"
            onClick={() => handleQuery()}
            disabled={status === 'submitting'}
          >
            {status === 'submitting' ? t.proQuery.querying : t.proQuery.query}
          </button>
        )}

        {isTokenMode && tokenStatus === 'token-loading' && (
          <div className="proquery__result" role="status">
            <p className="proquery__result-title">{t.proQuery.tokenQuerying}</p>
          </div>
        )}

        {isTokenMode && tokenStatus === 'token-invalid' && (
          <div className="proquery__result is-error" role="alert">
            <p className="proquery__result-title">{t.proQuery.tokenInvalidTitle}</p>
            <p className="proquery__result-hint">{t.proQuery.tokenInvalidHint}</p>
          </div>
        )}

        {isTokenMode && tokenStatus === 'token-ok' && tokenResult && (
          <LicenseResults
            licenses={tokenResult.licenses}
            withDevices
            showHint={false}
            onRevoke={handleRevokeClick}
          />
        )}

        {!isTokenMode && status === 'license' && result?.found === 'license' && (
          <>
            <LicenseResults licenses={result.licenses} />
            {firstQueryLink && (
              <p className="proquery__dev-link">
                {t.proQuery.devQueryLinkLabel}:{' '}
                <a className="proquery__dev-link" href={firstQueryLink}>
                  {firstQueryLink}
                </a>
              </p>
            )}
          </>
        )}

        {!isTokenMode && status === 'orders' && result?.found === 'orders' && (
          <div className="proquery__result" role="status">
            <p className="proquery__result-title">{t.proQuery.ordersFoundTitle}</p>
            <p className="proquery__result-hint">{t.proQuery.ordersUnpaidHint}</p>
            <div className="proquery__orders">
              {result.orders.map((order) => (
                <div className="proquery__order" key={order.order_id}>
                  <span className="proquery__order-label">
                    {t.proQuery.orderIdLabel}:{' '}
                    <code className="proquery__order-value">{order.order_id}</code>
                  </span>
                  <span className="proquery__order-label">
                    {t.proQuery.statusLabel}:{' '}
                    <span className="proquery__order-status">
                      {order.status === 'pending'
                        ? t.proQuery.statusPending
                        : order.status}
                    </span>
                  </span>
                </div>
              ))}
            </div>
            <p className="proquery__result-hint">{t.proQuery.ordersActionHint}</p>
          </div>
        )}

        {!isTokenMode && status === 'none' && (
          <div className="proquery__result" role="status">
            <p className="proquery__result-title">{t.proQuery.noneTitle}</p>
            <p className="proquery__result-hint">{t.proQuery.noneHint}</p>
          </div>
        )}

        {!isTokenMode && status === 'error' && (
          <div className="proquery__result is-error" role="alert">
            <p className="proquery__result-title">{t.proQuery.errorTitle}</p>
            <p className="proquery__result-hint">{errorMsg}</p>
            <button
              type="button"
              className="proquery__retry"
              onClick={() => handleQuery()}
            >
              {t.proQuery.retry}
            </button>
          </div>
        )}

        
        <div className="proquery__actions">
          <p className="proquery__contact">
            {t.proQuery.contactLabel}
            <a href={`mailto:${t.proQuery.contactEmail}`} className="proquery__contact-mail">
              {t.proQuery.contactEmail}
            </a>
          </p>
          <Link to="/buy_pro" className="proquery__backbuy">
            {t.proQuery.backBuy}
          </Link>
        </div>


        {revokeTarget && (
          <div className="proquery__modal" role="dialog" aria-modal="true">
            <div className="proquery__modal-card">
              <p className="proquery__modal-title">
                {t.proQuery.revokeTitle}
              </p>
              <p className="proquery__modal-hint">
                {format(t.proQuery.revokeConfirmHint, { device: revokeTarget.name })}
              </p>
              {revokeError && (
                <p className="proquery__modal-error" role="alert">
                  {revokeError}
                </p>
              )}
              <div className="proquery__modal-actions">
                <button
                  type="button"
                  className="proquery__modal-cancel"
                  onClick={() => setRevokeTarget(null)}
                  disabled={revoking}
                >
                  {t.proQuery.cancel}
                </button>
                <button
                  type="button"
                  className="proquery__modal-ok"
                  onClick={confirmRevoke}
                  disabled={revoking}
                >
                  {revoking ? t.proQuery.revoking : t.proQuery.confirmRevoke}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </PaymentLayout>
  );
}