import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useI18n, format } from '../i18n';
import {
  fetchOrder,
  OrderNotFoundError,
  type PaymentChannel,
} from '../lib/paymentApi';
import PaymentLayout from '../components/PaymentLayout';
import './PayReturnPage.css';

const MAX_ATTEMPTS = 10;
const POLL_INTERVAL_MS = 3000;

/** 邮箱脱敏：@前只保留首字母，其余为*；@后域名保留最后一段(.com/.cn等)，
 *  中间段每段只保留首字母 + 全部"."，其余为*。例：bob@example.com -> b**@e******.com */
function maskEmail(email: string): string {
  const at = email.indexOf('@');
  if (at <= 0) return email;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  const maskPart = (s: string) => (s.length <= 1 ? s : s[0] + '*'.repeat(s.length - 1));
  const maskedLocal = maskPart(local);
  const domainParts = domain.split('.');
  const last = domainParts[domainParts.length - 1];
  const maskedMiddle = domainParts
    .slice(0, -1)
    .map(maskPart)
    .join('.');
  return `${maskedLocal}@${maskedMiddle}.${last}`;
}

type Status =
  | 'loading'
  | 'pending'
  | 'paid'
  | 'failed'
  | 'missing';

export default function PayReturnPage() {
  const { t } = useI18n();

  const [orderId, setOrderId] = useState<string | null>(null);
  const [channel, setChannel] = useState<PaymentChannel | null>(null);
  const [status, setStatus] = useState<Status>('loading');
  const [attempt, setAttempt] = useState(0);
  const [retryKey, setRetryKey] = useState(0);
  const [orderEmail, setOrderEmail] = useState<string | null>(null);

  // 首次挂载解析 URL 参数
  // 两种入参形式：
  //   1) ?out_trade_no=xxx                  (alipay 通道，orderId 是本地订单号)
  //   2) ?payment_channel=paddle&transaction_id=txn_xxx
  //                                          (paddle 通道，orderId 是 Paddle 交易 ID)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const txnId = params.get('transaction_id');
    const channelParam = params.get('payment_channel');
    if (txnId && channelParam === 'paddle') {
      setOrderId(txnId);
      setChannel('paddle');
    } else {
      const id = params.get('out_trade_no');
      if (!id) {
        setStatus('missing');
        return;
      }
      setOrderId(id);
      setChannel(null);
    }
    setStatus('loading');
    setAttempt(0);
  }, [retryKey]);

  // 轮询订单状态
  useEffect(() => {
    if (!orderId) return;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let attempts = 0;

    const check = async () => {
      attempts += 1;
      setAttempt(attempts);
      try {
        const order = await fetchOrder(orderId, channel ? { channel } : undefined);
        if (cancelled) return;
        if (order.email) setOrderEmail(order.email);
        if (order.status === 'paid') {
          setStatus('paid');
          return;
        }
        if (order.status === 'expired') {
          setStatus('failed');
          return;
        }
        // pending：3 秒后重查，最多 MAX_ATTEMPTS 次
        if (attempts >= MAX_ATTEMPTS) {
          setStatus('failed');
          return;
        }
        setStatus('pending');
        timer = setTimeout(check, POLL_INTERVAL_MS);
      } catch (e) {
        if (cancelled) return;
        if (e instanceof OrderNotFoundError) {
          setStatus('failed');
          return;
        }
        // 网络/临时错误：重试，达到上限则失败
        if (attempts >= MAX_ATTEMPTS) {
          setStatus('failed');
          return;
        }
        setStatus('pending');
        timer = setTimeout(check, POLL_INTERVAL_MS);
      }
    };

    check();
    return () => {
      cancelled = true;
      if (timer) clearTimeout(timer);
    };
  }, [orderId, channel, retryKey]);

  return (
    <PaymentLayout>
      <div className="payreturn">
        <h1 className="payreturn__title">{t.payReturn.title}</h1>

        {orderId && (
          <div className="payreturn__order">
            <span className="payreturn__order-label">{t.payReturn.orderIdLabel}</span>
            <code className="payreturn__order-value">{orderId}</code>
          </div>
        )}

        {(status === 'loading' || status === 'pending') && (
          <div className="payreturn__state" role="status">
            <span className="payreturn__spinner" aria-hidden="true" />
            <p className="payreturn__state-title">
              {status === 'loading' ? t.payReturn.checking : t.payReturn.pendingTitle}
            </p>
            {status === 'pending' && (
              <p className="payreturn__state-meta">
                {format(t.payReturn.attempt, { current: String(attempt), max: String(MAX_ATTEMPTS) })}
              </p>
            )}
          </div>
        )}

        {status === 'paid' && (
          <div className="payreturn__state is-success" role="status">
            <span className="payreturn__icon is-success" aria-hidden="true">
              <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M20 6L9 17l-5-5" />
              </svg>
            </span>
            <p className="payreturn__state-title">{t.payReturn.successTitle}</p>
            <p className="payreturn__state-meta">
              {orderEmail
                ? format(t.payReturn.successHint, { email: maskEmail(orderEmail) })
                : t.payReturn.successHint.replace(' {email}', '')}
            </p>
          </div>
        )}

        {status === 'failed' && (
          <div className="payreturn__state is-error" role="alert">
            <span className="payreturn__icon is-error" aria-hidden="true">
              <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="10" />
                <path d="M12 8v4M12 16h.01" />
              </svg>
            </span>
            <p className="payreturn__state-title">{t.payReturn.failTitle}</p>
            <p className="payreturn__state-meta">{t.payReturn.failHint}</p>
            <button type="button" className="payreturn__retry" onClick={() => setRetryKey((k) => k + 1)}>
              {t.payReturn.retry}
            </button>
          </div>
        )}

        {status === 'missing' && (
          <div className="payreturn__state is-error" role="alert">
            <p className="payreturn__state-title">{t.payReturn.missingTitle}</p>
            <p className="payreturn__state-meta">{t.payReturn.missingHint}</p>
          </div>
        )}

        <Link to="/" className="payreturn__home">
          {t.payReturn.back}
        </Link>
      </div>
    </PaymentLayout>
  );
}