import { useEffect, useState } from 'react';
import { useScrollReveal } from '../hooks/useScrollReveal';
import { useI18n, format } from '../i18n';
import { detectOS, detectArch, PLATFORMS, OS, Arch, Platform } from '../utils/detectOS';
import './Download.css';

