function getRecommendedArch(platform: Platform, detectedArch: Arch): string | null {
  if (platform.os === 'macos') {
    if (detectedArch === 'arm64') return 'Apple Silicon';
    if (detectedArch === 'x64') return 'Intel';
  }
  if (platform.os === 'windows' || platform.os === 'linux') {
    if (detectedArch === 'x64' || detectedArch === 'arm64') return 'x64';
  }
  return null;
}

export default function Download() {
  const { t } = useI18n();
  const [detectedOS, setDetectedOS] = useState<OS>('unknown');
  const [detectedArch, setDetectedArch] = useState<Arch>('unknown');
  const { ref, isRevealed } = useScrollReveal<HTMLDivElement>();

  useEffect(() => {
    setDetectedOS(detectOS());
    setDetectedArch(detectArch());
  }, []);

  const osLabel = detectedOS === 'macos' ? 'macOS' : detectedOS === 'windows' ? 'Windows' : detectedOS === 'linux' ? 'Linux' : null;

  return (
    <section className="download" id="download">
      <div className="container">
        <div
          ref={ref}
          className={`reveal ${isRevealed ? 'revealed' : ''}`}
        >
          <div className="download__header">
            <h2 className="download__title">{t.download.title}</h2>
            <p className="download__subtitle">
              {osLabel
                ? format(t.download.detected, { os: osLabel })
                : t.download.choose}
            </p>
          </div>
        </div>

        <div className="download__platforms">
          {PLATFORMS.map((platform, i) => {
            const isRecommendedPlatform = platform.os === detectedOS;
            const recommendedArch = getRecommendedArch(platform, detectedArch);

            return (
              <div
                key={platform.os}
                className={`reveal download-platform ${isRecommendedPlatform ? 'download-platform--recommended' : ''} ${isRevealed ? 'revealed' : ''}`}
                style={{ transitionDelay: `${i * 100}ms` }}
              >
                <div className="download-platform__header">
                  <div className="download-platform__icon">
                    <OSIcon os={platform.icon} />
                  </div>
                  <div className="download-platform__title">
                    <span className="download-platform__name">{platform.label}</span>
                    {isRecommendedPlatform && (
                      <span className="download-platform__badge">
                        <span className="pulse-dot" />
                        {t.download.recommended}
                      </span>
                    )}
                  </div>
                </div>

                <div className="download-platform__downloads">
                  {platform.downloads.map((dl) => {
                    const isRecommendedItem = isRecommendedPlatform && dl.arch === recommendedArch;
                    return (
                      <div
                        key={dl.id}
                        className={`download-item ${isRecommendedItem ? 'download-item--recommended' : ''}`}
                      >
                        <div className="download-item__info">
                          <span className="download-item__arch">{dl.arch}</span>
                          <span className="download-item__meta">{dl.format} · {dl.size}</span>
                        </div>
                        <a
                          href={dl.href}
                          className={`download-item__btn ${isRecommendedItem ? 'download-item__btn--primary' : ''}`}
                          onClick={(e) => e.preventDefault()}
                        >
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3" />
                          </svg>
                          {isRecommendedItem ? t.download.recommendedDownload : t.download.download}
                        </a>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
